"use client";

import { useEffect, useState } from "react";
import { GhibliRobotHero } from "@/components/ui/ghibli-robot-hero";

/** True while the viewport is narrow. Drives the crop and the copy width below. */
function useNarrow(query = "(max-width: 767px)") {
  const [narrow, setNarrow] = useState(false);
  useEffect(() => {
    const m = window.matchMedia(query);
    const sync = () => setNarrow(m.matches);
    sync();
    m.addEventListener("change", sync);
    return () => m.removeEventListener("change", sync);
  }, [query]);
  return narrow;
}

/**
 * The background, carried inline so this demo needs nothing hosted alongside
 * it. Swap it for your own picture — any wide, bright landscape works, so long
 * as the top third is quiet, since that is where the words go.
 *
 * On a real site pass a URL instead, and give `sources` two or three widths of
 * it. The hero runs the full height of the screen, so the browser crops hard
 * and a large file is not a luxury: below about 2700px across it has to enlarge
 * the picture to fill a retina desktop, and the grass is the first thing to go.
 * This copy is 2600px. It is not larger because 21st caps a demo file at
 * 200KB, and the base64 has to live in this source. Pass a hosted URL and
 * `sources` to get the full 5504px file with none of that ceiling.
 */
export const GRYPHON_HERO_BACKGROUND = "data:image/webp;base64,";

/** A small mark for the button. Inline, so the demo pulls in no icon package. */
function SparkIcon() {
  return (
    <svg
      width="16"
      height="16"
      viewBox="0 0 24 24"
      fill="currentColor"
      aria-hidden="true"
    >
      <path d="M12 2.5l1.9 5.9a4 4 0 0 0 2.6 2.6l5.9 1.9-5.9 1.9a4 4 0 0 0-2.6 2.6L12 23.4l-1.9-5.9a4 4 0 0 0-2.6-2.6L1.6 12.9l5.9-1.9a4 4 0 0 0 2.6-2.6L12 2.5z" />
    </svg>
  );
}

/**
 * The picture does most of the work here, so the copy stays out of its way:
 * one line of headline, one line under it, one button.
 *
 * Two settings do the fitting. `focus` holds the horizon and the robot in frame
 * however the section is cropped — a landscape cut to a hero loses its top and
 * bottom first, and the default centre crop would throw away the sky. `lead`
 * puts the block at just under a third down, which on this picture lands the
 * headline in open blue and the button clear of the far ridge.
 *
 * A phone crops the same picture to about a third of its width. Held at 62% it
 * would show the robot and little else, with the copy landing on top of him, so
 * there the frame slides left to the lake and the copy rides higher.
 */
export default function GhibliRobotHeroDemo() {
  const narrow = useNarrow();

  return (
    <GhibliRobotHero
      image={GRYPHON_HERO_BACKGROUND}
      imageAlt="A humanoid robot on a stone path above a lake, under tall summer clouds"
      focus={narrow ? "38% 64%" : "62% 58%"}
      lead={narrow ? 0.34 : 0.42}
      scrim={0}
      title="Humanoid robots for outdoor work"
      subtitle="Farms, substations, building sites."
      ctaLabel="Automate the outdoors"
      ctaIcon={<SparkIcon />}
    />
  );
}
